import math

PPD = 20.0
HZ = 90.0

def bulanik(omega, ms):
    derece = omega * ms / 1000.0
    return derece, derece * PPD

print("kare suresi ms:", round(1000 / HZ, 3))
for ms in (11.111, 4.0, 2.0, 0.5):
    d, px = bulanik(100.0, ms)
    print("kalicilik", ms, "ms ->", round(d, 4), "derece,", round(px, 2), "piksel")

duty = 2.0 / (1000.0 / HZ)
print("duty:", round(duty, 4), "| parlaklik carpani:", round(1 / duty, 2))

def bozulma(r, k1, k2):
    return r * (1 + k1 * r * r + k2 * r ** 4)

for r in (0.25, 0.5, 0.75, 1.0):
    print("r =", r, "-> rd =", round(bozulma(r, 0.22, 0.24), 4))

for s in (1.2, 1.4, 1.46):
    print("render olcegi", s, "-> px carpani", round(s * s, 3),
          "| goz basina", round(2000 * 2000 * s * s / 1e6, 2), "Mpx")

pitch = 60.0 / PPD
for ff in (0.40, 0.70, 0.85):
    lin = math.sqrt(ff)
    print("dolum", ff, "-> bosluk", round((1 - lin) * pitch, 3), "arcmin")

import math

def aci_hatasi(yanlilik, t):
    return yanlilik * t

def konum_hatasi(ivme_yanliligi, t):
    return 0.5 * ivme_yanliligi * t * t

print("--- jiroskop yanliligi 0.02 derece/s ---")
for t in (1, 10, 60, 300):
    print(" t =", t, "s ->", round(aci_hatasi(0.02, t), 4), "derece")

print("--- ivmeolcer yanliligi 0.01 m/s^2 (cift integral) ---")
for t in (1, 5, 10, 60):
    print(" t =", t, "s ->", round(konum_hatasi(0.01, t) * 1000, 3), "mm")

print("--- aci rastgele yurumesi 0.5 derece/sqrt(saat) ---")
for t in (60, 300, 3600):
    print(" t =", t, "s ->", round(0.5 * math.sqrt(t / 3600), 4), "derece")

print("--- 3DoF ile 10 cm oteleme ---")
for d in (0.5, 1.0, 2.0, 5.0):
    print(" nesne", d, "m ->", round(math.degrees(math.atan(0.10 / d)), 4), "derece hata")

print("--- tamamlayici suzgec katsayisi ---")
for tau, dt in ((0.5, 0.001), (0.5, 0.005), (2.0, 0.001)):
    print(" tau =", tau, "dt =", dt, "-> alfa =", round(tau / (tau + dt), 6))

import math

def kati_aci(fov_derece):
    return 2 * math.pi * (1 - math.cos(math.radians(fov_derece / 2)))

taban = kati_aci(100)
for fov in (100, 80, 60, 40):
    o = kati_aci(fov)
    print("FOV", fov, "-> kati aci", round(o, 4), "sr | 100 dereceye oran", round(o / taban, 4))
print("tunelleme 100 -> 60: gorsel alanin", round((1 - kati_aci(60) / taban) * 100, 2), "% azalmasi")

