import math

A, B = 0.25, 0.18          # olculmus varsayim: MT = A + B * ID

def acisal(genislik_m, mesafe_m):
    return 2 * math.degrees(math.atan(genislik_m / 2 / mesafe_m))

def fitts(D_derece, W_derece):
    ID = math.log2(2 * D_derece / W_derece)
    return round(ID, 4), round(A + B * ID, 4)

for w, d in ((0.05, 2.0), (0.05, 0.5), (0.10, 2.0), (0.02, 2.0)):
    print("hedef", w, "m @", d, "m ->", round(acisal(w, d), 4), "derece")

for D, W in ((20.0, 1.5), (20.0, 3.0), (40.0, 1.5), (10.0, 5.0)):
    ID, MT = fitts(D, W)
    print("D =", D, "W =", W, "-> ID =", ID, "bit, MT =", MT, "s")

for titreme in (0.3, 0.5, 1.0):
    satir = []
    for d in (1, 3, 5):
        satir.append(round(d * math.radians(titreme) * 1000, 2))
    print("titreme", titreme, "derece -> yanal (1/3/5 m):", satir, "mm")

for d in (2.0, 5.0):
    print("1.5 derecelik hedef @", d, "m ->",
          round(2 * d * math.tan(math.radians(0.75)) * 1000, 2), "mm")

print("kol statik torku:", round(3.2 * 9.81 * 0.30, 3), "N.m")

import math

C = 343.0        # ses hizi m/s
R = 0.0875       # kafa yaricapi m

def itd_kuresel(deg):
    th = math.radians(deg)
    return R / C * (th + math.sin(th)) * 1e6

def itd_basit(deg):
    return 0.18 * math.sin(math.radians(deg)) / C * 1e6

for deg in (0, 15, 30, 60, 90):
    print(deg, "derece -> ITD kuresel", round(itd_kuresel(deg), 2),
          "us | basit", round(itd_basit(deg), 2), "us")

for d in (1, 2, 5, 10, 20):
    print("mesafe", d, "m -> ses yol suresi", round(d / C * 1000, 3), "ms")

for k in (2, 4, 10):
    print("mesafe", k, "kat -> seviye", round(-20 * math.log10(k), 2), "dB")

for v in (1.4, 3.0, 10.0):
    print("kaynak", v, "m/s yaklasiyor -> 1000 Hz ->",
          round(1000 * C / (C - v), 2), "Hz")

for n in (128, 256, 512, 1024):
    print("arabellek", n, "ornek @48 kHz ->", round(n / 48000 * 1000, 3), "ms")

haptik = [("temas belirleme", 1.0), ("fizik adimi", 2.0), ("titresim komutu", 1.5),
          ("aktuator yukselme", 8.0)]
print("haptik toplam:", round(sum(v for _, v in haptik), 2), "ms")

import math

def yuzey_parlakligi(lux, albedo=0.5):
    return lux * albedo / math.pi

for ad, E in (("dogrudan gunes", 100000), ("bulutlu gun", 10000), ("kapali ofis", 500)):
    L = yuzey_parlakligi(E)
    print(ad.ljust(15), E, "lux ->", round(L, 1), "cd/m2 | %30 gecirgenlikte",
          round(L * 0.3, 1), "cd/m2")

for ad, E in (("dogrudan gunes", 100000), ("kapali ofis", 500)):
    Lb = yuzey_parlakligi(E) * 0.3
    for C in (1.5, 2.0, 3.0):
        print(ad.ljust(15), "kontrast", C, "-> ekran", round(Lb * (C - 1), 1), "cd/m2")

h = 0.20
for yukseklik in (30, 45, 60):
    L = h / math.tan(math.radians(yukseklik))
    for azimut_hata in (10, 20):
        kayma = L * 2 * math.sin(math.radians(azimut_hata / 2))
        print("gunes", yukseklik, "derece | golge", round(L * 1000, 1),
              "mm | azimut hatasi", azimut_hata, "-> uc kaymasi", round(kayma * 1000, 2), "mm")

hata = {"izleme": 0.30, "gecikme": 0.68, "kalibrasyon": 0.20, "goz konumu": 0.15}
dogrusal = sum(hata.values())
karekok = math.sqrt(sum(v * v for v in hata.values()))
print("toplam dogrusal:", round(dogrusal, 3), "derece | karekok:", round(karekok, 4), "derece")
for d in (0.5, 1.0, 2.0):
    print(" d =", d, "m -> yanal", round(math.radians(karekok) * d * 1000, 2), "mm")

for e in (0.01, 0.02, 0.05):
    print("olcek hatasi", e, "-> 2 m'de", round(e * 2 * 1000, 1), "mm")
